using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;

namespace IPv8.Tests
{
    /// <summary>
    /// Loader for the Phase 2 golden vectors (contract/vectors-phase2.json, copied next to the
    /// test assembly). Generated by contract/gen_vectors_phase2.py against py-ipv8's own
    /// attestation classes (deterministic urandom + seeded primes).
    /// </summary>
    public static class Vectors2
    {
        private static readonly Lazy<JsonElement> Root = new Lazy<JsonElement>(LoadRoot);

        private static JsonElement LoadRoot()
        {
            var path = Path.Combine(AppContext.BaseDirectory, "vectors-phase2.json");
            var json = File.ReadAllText(path);
            return JsonDocument.Parse(json).RootElement.Clone();
        }

        private static JsonElement RootElement => Root.Value;

        public static string Meta(string key) => RootElement.GetProperty("meta").GetProperty(key).GetString();

        public static string MetaKey(string key)
            => RootElement.GetProperty("meta").GetProperty("keys").GetProperty(key).GetString();

        public static JsonElement Section(string key) => RootElement.GetProperty(key);

        public static string SectionString(string section, string key)
            => RootElement.GetProperty(section).GetProperty(key).GetString();

        /// <summary>ipack entries: {"num": str, "packed_hex": hex}.</summary>
        public static IEnumerable<(string Num, string PackedHex)> IpackVectors()
        {
            foreach (var entry in Section("ipack").EnumerateArray())
            {
                yield return (entry.GetProperty("num").GetString(), entry.GetProperty("packed_hex").GetString());
            }
        }

        /// <summary>fp2 entries: {"mod", "a", "b", "op", "out_a", "out_b"}.</summary>
        public static IEnumerable<(long Mod, long A, long B, string Op, string OutA, string OutB)> Fp2Vectors()
        {
            foreach (var entry in Section("fp2").EnumerateArray())
            {
                yield return (entry.GetProperty("mod").GetInt64(),
                              entry.GetProperty("a").GetInt64(),
                              entry.GetProperty("b").GetInt64(),
                              entry.GetProperty("op").GetString(),
                              entry.GetProperty("out_a").GetString(),
                              entry.GetProperty("out_b").GetString());
            }
        }

        public static string BonehKey(string key)
            => Section("boneh").GetProperty("key").GetProperty(key).GetString();

        public static IEnumerable<(long M, string CipherA, string CipherB)> BonehEncodeDecode()
        {
            foreach (var entry in Section("boneh").GetProperty("encode_decode").EnumerateArray())
            {
                yield return (entry.GetProperty("m").GetInt64(),
                              entry.GetProperty("cipher_a").GetString(),
                              entry.GetProperty("cipher_b").GetString());
            }
        }

        public static string ShaAsInt(string key)
            => Section("boneh").GetProperty("sha_as_int").GetProperty(key).GetString();

        public static JsonElement BonehAttestation => Section("boneh").GetProperty("attestation");

        public static JsonElement BonehAttestationBig => Section("boneh").GetProperty("attestation_big");

        public static JsonElement PengBao => Section("pengbao");

        public static string WalletPrefixHex => Meta("wallet_prefix_hex");

        public static IEnumerable<(int MsgId, string Name, string PacketHex, long GlobalTime)> WalletPackets()
        {
            foreach (var entry in Section("wallet_packets").EnumerateArray())
            {
                yield return (entry.GetProperty("msg_id").GetInt32(),
                              entry.GetProperty("name").GetString(),
                              entry.GetProperty("packet_hex").GetString(),
                              entry.GetProperty("global_time").GetInt64());
            }
        }
    }
}
